mapper.select:
SELECT COUNT(*)
FROM PAY_CALLBACK_LOG
WHERE MERCHANT_ORDER_NO = #{merchantOrderNo,jdbcType=VARCHAR}
  AND CALLBACK_TYPE = #{callbackType,jdbcType=VARCHAR}

mapper.update:
UPDATE PAY_CALLBACK_LOG
SET HANDLE_STATUS = 'MANUAL',
    HANDLE_MSG = #{handleMsg,jdbcType=VARCHAR}
WHERE ID = (
    SELECT MAX(ID)
    FROM PAY_CALLBACK_LOG
    WHERE MERCHANT_ORDER_NO = #{merchantOrderNo,jdbcType=VARCHAR}
      AND CALLBACK_TYPE = #{callbackType,jdbcType=VARCHAR}
)

mapper.select:
SELECT MERCHANT_ORDER_NO, DISCOUNT_INFO FROM ( SELECT MERCHANT_ORDER_NO, DISCOUNT_INFO, ROW_NUMBER() OVER ( PARTITION BY MERCHANT_ORDER_NO ORDER BY CREATE_TIME DESC, ID DESC ) AS RN FROM PAY_CALLBACK_LOG WHERE CALLBACK_TYPE = #{callbackType,jdbcType=VARCHAR} AND DISCOUNT_INFO IS NOT NULL AND MERCHANT_ORDER_NO IN
#{orderNo,jdbcType=VARCHAR}
) WHERE RN = 1
